def classify_event_risk(event_direction,direction,config=None):
    with_event=(event_direction=="up" and direction=="buy") or (event_direction=="down" and direction=="sell");section=(config or {}).get("with_event" if with_event else "against_event",{});relationship="with_event" if with_event else "post_recovery" if (event_direction=="down" and direction=="buy") else "against_event"
    return {"relationship":relationship,"event_direction":event_direction,"gap_risk":"moderate" if with_event else "high","slippage_risk":"high" if with_event else "extreme","minimum_required_rr":float(section.get("minimum_tp1_rr",1.5 if with_event else 2)),"maximum_chase_atr":float(section.get("maximum_chase_atr",.35 if with_event else .25)),"setup_lifetime_candles":int(section.get("setup_expiration_m5_candles",12 if with_event else 8)),"confirmation_requirement":"Completed post-event M5 structure confirmation." if with_event else "Strong completed opposite structure shift and retest.","warnings":[] if with_event else ["Scenario opposes or recovers from the original event."]}
